-- Attach a chosen accepted friend to a prepared question paper and schedule it.
-- The code generated by the legacy code flow is invalidated; the friend accepts
-- only through the authenticated invitation notification.
create or replace function public.edu_challenge_send_invite(
  p_password text,p_challenge_id uuid,p_opponent_id uuid,p_scheduled_at timestamptz
)
returns jsonb language plpgsql security definer set search_path=public,auth,extensions as $$
declare
  v_user uuid:=public.edu_challenge_assert_access(p_password);
  v_c public.edu_challenges%rowtype; v_invite_id uuid; v_opponent_username text;
begin
  if p_opponent_id is null or p_opponent_id=v_user then raise exception 'Choose another EDU-AFRIKA student.'; end if;
  if p_scheduled_at is null or p_scheduled_at<clock_timestamp()+interval '15 minutes'
    or p_scheduled_at>clock_timestamp()+interval '30 days' then
    raise exception 'Choose a challenge time at least 15 minutes from now and within the next 30 days.';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('EDU-CHALLENGE-USER:'||least(v_user::text,p_opponent_id::text),0));
  perform pg_advisory_xact_lock(hashtextextended('EDU-CHALLENGE-USER:'||greatest(v_user::text,p_opponent_id::text),0));
  select * into v_c from public.edu_challenges where id=p_challenge_id and creator_id=v_user for update;
  if not found or v_c.status<>'waiting' or v_c.opponent_id is not null then
    raise exception 'This prepared challenge is no longer available. Please create it again.';
  end if;
  if not exists(select 1 from public.edu_students s join public.profiles p on p.id=s.user_id
    where s.user_id=p_opponent_id and p.account_status='active') then
    raise exception 'That person is not an active EDU-AFRIKA student.';
  end if;
  if not exists(select 1 from public.friendships f where
    (f.user_a=v_user and f.user_b=p_opponent_id) or (f.user_a=p_opponent_id and f.user_b=v_user)) then
    raise exception 'You can schedule quiz challenges only with an accepted Frnxup friend. Connect as friends first.';
  end if;
  if exists(select 1 from public.user_blocks b where
    (b.blocker_id=v_user and b.blocked_id=p_opponent_id) or (b.blocker_id=p_opponent_id and b.blocked_id=v_user)) then
    raise exception 'This invitation cannot be sent because one of the accounts has blocked the other.';
  end if;
  if exists(select 1 from public.edu_challenges c where c.status in ('waiting','active')
    and (c.creator_id=p_opponent_id or c.opponent_id=p_opponent_id)) then
    raise exception 'That student already has an unfinished challenge. Try again after it is completed.';
  end if;
  select username into v_opponent_username from public.profiles where id=p_opponent_id;
  update public.edu_challenges set opponent_id=p_opponent_id,
    expires_at=greatest(expires_at,p_scheduled_at+interval '2 hours'),
    code_hash=encode(digest(gen_random_bytes(32),'sha256'),'hex')
  where id=p_challenge_id;
  insert into public.edu_challenge_invites(challenge_id,sender_id,recipient_id,scheduled_at)
    values(p_challenge_id,v_user,p_opponent_id,p_scheduled_at) returning id into v_invite_id;
  insert into public.notifications(user_id,actor_id,type,title,body,target_type,target_id)
    values(p_opponent_id,v_user,'edu_challenge_invite',
      'A STUDENT FROM EDU-AFRIKA INVITES YOU ON QUIZ CHALLENGE',
      '@'||coalesce((select username from public.profiles where id=v_user),'A student')||
      ' invited you to a timed EDU-AFRIKA quiz challenge with @'||coalesce(v_opponent_username,'student')||
      '. Scheduled time: '||p_scheduled_at::text,
      'edu_challenge_invite',v_invite_id);
  return jsonb_build_object('ok',true,'invitation_id',v_invite_id,'challenge_id',p_challenge_id,
    'recipient_username',v_opponent_username,'scheduled_at',p_scheduled_at,
    'message','Your quiz invitation has been sent. Your friend will receive an on-screen notification.');
end;
$$;
revoke all on function public.edu_challenge_send_invite(text,uuid,uuid,timestamptz) from public,anon;
grant execute on function public.edu_challenge_send_invite(text,uuid,uuid,timestamptz) to authenticated;
